/**
 * Test method calls with the CallMethodRule rule. It should be possible to call a method with no arguments using
 * several rule syntaxes.
 */
@Test
public void testBasic() throws SAXException, IOException {
    final Digester digester = newLoader(new AbstractRulesModule() {

        @Override
        protected void configure() {
            forPattern("employee").createObject().ofType(Employee.class);
            // try all syntax permutations
            forPattern("employee").callMethod("toString").withParamCount(0).withParamTypes((Class[]) null).then().callMethod("toString").withParamCount(0).withParamTypes((String[]) null).then().callMethod("toString").withParamCount(0).withParamTypes(new Class[] {}).then().callMethod("toString").withParamCount(0).withParamTypes(new String[] {}).then().callMethod("toString");
        }
    }).newDigester();
    // Parse our test input.
    // An exception will be thrown if the method can't be found
    final Employee root1 = digester.parse(getInputStream("Test5.xml"));
    assertNotNull(root1);
}

