public void testSettingProperties() throws SAXException, IOException {
    Digester digester = newLoader(new AbstractRulesModule() {

        @Override
        protected void configure() {
            forPattern("employee").createObject().ofType(Employee.class).then().callMethod("setLastName").withParamTypes("java.lang.String");
            forPattern("employee/lastName").callParam().ofIndex(0);
